import React, { Component, Fragment } from "react";
import { Container } from "reactstrap";
import { connect } from "react-redux";
import PropTypes from "prop-types";
import AppNavbar from "./AppNavbar";
import ShoppingList from "./ShoppingList";
import ItemModal from "./ItemModal";
import Clients from "./mainNav/Clients";
import Items from "./mainNav/Items";
import ConfigurationHistory from "./opsNav/ConfigurationHistory";
import AccessSetup from "./opsNav/AccessSetup";
import ProcessGroups from "./mainNav/ProcessGroups";
import AccessConfiguration from "./opsNav/AccessConfiguration";
import LoginPage from "./auth/LoginPage";

class Pages extends Component {
  render() {
    const processGroups = (
      <div>
        <ItemModal />
        <ShoppingList />
        <ProcessGroups />
      </div>
    );
    const mainNav = page => {
      switch (page.page) {
        case "ProcessGroups":
          return processGroups;
        case "Items":
          return <Items />;
        case "Clients":
          return <Clients />;
        default:
          return processGroups;
      }
    };
    const clientsNav = page => {
      switch (page.page) {
        default:
          return "Client Config";
      }
    };
    const opsNav = page => {
      switch (page.page) {
        case "ConfigurationHistory":
          return <ConfigurationHistory />;
        //return "config hx";
        case "AccessSetup":
          return <AccessSetup />;
        case "ViewAccess":
          return "ViewAccess";
        case "AccessConfiguration":
          return <AccessConfiguration />;
        default:
          return "Default OpsNav";
      }
    };
    function renderPageSwitch(page) {
      switch (page.navType) {
        case "MainNav":
          return mainNav(page);
        case "OpsNav":
          return opsNav(page);
        case "ClientsNav":
          return clientsNav(page);
        default:
          return mainNav(page);
      }
    }
    return (
      <div>
        {this.props.auth.isAuthenticated ? (
          <div>
            <AppNavbar />
            <Container style={{ marginTop: "7%" }}>
              {renderPageSwitch(this.props.page.page)}
            </Container>
          </div>
        ) : (
          <LoginPage /> //put in login page here
        )}
      </div>
    );
  }
}

Pages.propTypes = {
  page: PropTypes.object.isRequired
};

const mapStateToProps = state => ({
  page: state.page, //posts is from the root reducer. Items is from the postReducer, which is ultimately getting the action from the postAction.  This expression then allows for use of this.props.posts
  auth: state.auth
});

export default connect(mapStateToProps, null)(Pages);
